    role: Role = 'member',
    signal?: AbortSignal,
  ): Promise<void> {
    await this.client.post(`/${organizationId}/members/invite`, { email, role }, { signal });
  }

  async updateMemberRole(organizationId: number, memberId: number, role: Role, signal?: AbortSignal): Promise<void> {
